"""Exact current CUSTOMS AGENT TOWN browser snapshot.

This keeps the Render page in sync with the App Block while the town UI is
still changing quickly. The payload is gzip-compressed HTML; town_page_bp calls
`latest_town_html()` through the blueprint package runtime override.
"""

import base64
import gzip


_HTML_GZ_B64 = """[... truncated for brevity in display ...]QAA="""


def latest_town_html():
    return gzip.decompress(base64.b64decode(_HTML_GZ_B64)).decode("utf-8")
